import{_ as o,a0 as m,w as i,s as r,ao as n,I as l,x as t,a1 as p,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"KDE Plasma 5.24：精心制作的主宰 Linux 世界的桌面 | LCTT x X-CMD","titleTemplate":false,"description":"KDE Plasma 5.24：精心制作的主宰 Linux 世界的桌面 | LCTT (202203) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"KDE Plasma 5.24：精心制作的主宰 Linux 世界的桌面 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"KDE Plasma 5.24：精心制作的主宰 Linux 世界的桌面 | LCTT (202203) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202203/20220310 KDE Plasma 5.24 Review. A Crafted Desktop to Dominate the Linux World","title":"KDE Plasma 5.24：精心制作的主宰 Linux 世界的桌面","tag":"202203","desc":""},"relativePath":"202203/20220310 KDE Plasma 5.24 Review. A Crafted Desktop to Dominate the Linux World.md","filePath":"[post].md"}'),d={name:"202203/20220310 KDE Plasma 5.24 Review. A Crafted Desktop to Dominate the Linux World.md"};function u(P,a,D,f,w,E){const s=m("Link");return i(),r("div",null,[a[28]||(a[28]=n('<h1 id="kde-plasma-5-24-精心制作的主宰-linux-世界的桌面" tabindex="-1">KDE Plasma 5.24：精心制作的主宰 Linux 世界的桌面 <a class="header-anchor" href="#kde-plasma-5-24-精心制作的主宰-linux-世界的桌面" aria-label="Permalink to “KDE Plasma 5.24：精心制作的主宰 Linux 世界的桌面”">​</a></h1><blockquote><p>是时候对前段时间发布的 KDE Plasma 5.24 桌面进行一次简单的回顾和点评了。</p></blockquote><p>KDE 团队用他们完美的 KDE Plasma 5.24 再次做到了。一个在效率、新功能、性能、稳定性和一切方面都非常完美的版本为所有用户带来了一个优秀的桌面环境。</p><p>KDE Plasma 5.24 是 Plasma 的第 26 个版本，也是长期支持（LTS）版本，它将为 Kubuntu 22.04 LTS Jammy Jellyfish 添彩。这意味着你、我和全世界成千上万的用户将使用这个版本两年或更长的时间。你可以想象这个版本是多么重要。</p><p>不多说了，让我们去快速点评一下 KDE Plasma 5.24。</p><p><img src="https://img.linux.net.cn/data/attachment/album/202203/12/202450k5x811c83661w3ix.jpg" alt="KDE Plasma 5.24 桌面"></p><h3 id="kde-plasma-5-24-点评" tabindex="-1">KDE Plasma 5.24 点评 <a class="header-anchor" href="#kde-plasma-5-24-点评" aria-label="Permalink to “KDE Plasma 5.24 点评”">​</a></h3><h4 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to “安装”">​</a></h4>',8)),l("p",null,[a[2]||(a[2]=t("我在 Fedora 上使用 ",-1)),p(s,{href:"https://www.debugpoint.com/2022/01/kde-plasma-5-24/"},{default:e(()=>[...a[0]||(a[0]=[t("KDE Plasma 5.24",-1)])]),_:1}),a[3]||(a[3]=t(" 已经有一段时间了。这次是直接从 ",-1)),p(s,{href:"https://www.debugpoint.com/2021/08/kde-plasma-5-23/"},{default:e(()=>[...a[1]||(a[1]=[t("KDE Plasma 5.23",-1)])]),_:1}),a[4]||(a[4]=t(" 升级而来。在升级过程中，一切都很顺利。所有的用户配置的设置都保持不变，只有默认的壁纸在升级后被改变了。所以，数据或启动加载出现问题是几乎不可能的。",-1))]),a[29]||(a[29]=n('<p>我在一个实体系统中安装了 KDE Plasma 5.24 和 KDE Neon 用户版以进一步测试。在一个 4GB 内存的英特尔 i3 系统中，安装很顺利，大约花了 8 分钟。</p><p>这个测试系统上还有另一个操作系统，所以安装程序完美地检测到了所有的操作系统并正确地更新了 GRUB。</p><h4 id="新功能、外观和可用性" tabindex="-1">新功能、外观和可用性 <a class="header-anchor" href="#新功能、外观和可用性" aria-label="Permalink to “新功能、外观和可用性”">​</a></h4><p>Plasma 5.24 看起来很震撼。第一次启动后呈现出一个干净的桌面，具有经典的外观和极其漂亮的壁纸。默认的 Breeze Light 主题加上新的边框和装饰，对每个用户来说几乎是完美的。如果你很好奇，想给你的 Plasma 换一个不同的外观，那么所有的设置，如重点颜色之类的都在那里。你不需要通过什么秘籍或命令行来改变外观。</p><p>新设计的概览屏幕给你一种 GNOME 的氛围，但在 KDE 环境下，当你设置好它时，它就会变得非常棒。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/11/KDE-Plasma-Overview-Effect-1-1024x434.jpg" alt="KDE Plasma 概览效果"></p><p>在我的测试中，我尝试了蓝牙、Wi-Fi 和打印（安装 HPLIP 后）—— 都很顺利。没有磕磕绊绊，也不需要命令行，一切都开箱即用。KDE Plasma 的通知区应该可以让你访问所有必要的选项，你很少需要访问系统设置对话框。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/03/Easy-Bluetooth-Setup.jpg" alt="蓝牙设置很简单"></p><p>电池使用情况尚可，我认为在我的测试硬件上，自 Plasma 5.23 以来，电池使用情况略有改善。我把测试机保持在待机状态，Plasma 很轻松就唤醒了，没有任何问题。我知道有些 Linux 发行版在睡眠后无法唤醒，导致你得在 TTY 里重启或启动 X 会话。</p><h4 id="稳定性和性能" tabindex="-1">稳定性和性能 <a class="header-anchor" href="#稳定性和性能" aria-label="Permalink to “稳定性和性能”">​</a></h4><p>不管你是一个 Plasma 的新用户还是长期用户，Plasma 5.24 都会让你有宾至如归的感觉；一切都准备好了，没有错误，等待你的行动和工作流程。</p>',11)),l("p",null,[a[6]||(a[6]=t("在我的测试期间中，我没有遇到任何错误。因此，我 ",-1)),p(s,{href:"https://forum.kde.org/search.php?keywords=5.24&terms=all&author=&tags=&sv=0&sc=1&sf=all&sr=posts&sk=t&sd=d&st=30&ch=300&t=0&submit=Search"},{default:e(()=>[...a[5]||(a[5]=[t("快速翻阅",-1)])]),_:1}),a[7]||(a[7]=t(" 了 KDE 官方论坛，看看在发布后的一个月内报告了多少种问题以及有多少问题。不多，实际上只有寥寥两位数。而且报告的问题大多与高端显示器和网络有关，我觉得这与特定的专业硬件有关。",-1))]),a[30]||(a[30]=n('<p>但总的来说，如今它是一个构建良好且经过测试的桌面。</p><p>在过去的几个版本中，KDE Plasma 在任何硬件上的性能都是完美的。而这个版本也证明了这一点。</p><p>在空闲阶段，KDE Plasma 5.24 消耗了 614MB 的内存，CPU 使用率为 2%。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/03/KDE-Plasma-5.24-Performance-in-Idle-Mode.jpg" alt="KDE Plasma 5.24 在闲置模式下的性能"></p><p>我通过 Firefox 运行了五个标签，并播放了 Youtube。同时，用一个文件管理器、文本编辑器、图片浏览器、系统设置和“发现”包管理器的实例来测试重载下的性能。这个用例使用了 1.29GB 的内存，而 CPU 平均在 6% 到 7%。</p><p>显然，Firefox 消耗了大部分的系统资源。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/03/KDE-Plasma-5.24-in-Heavy-Workload-Mode.jpg" alt="KDE Plasma 5.24 在重度工作负载模式下"></p><p>我必须说，这是一个了不起的性能指标。</p><p>所以，有了这个版本，就有了一个完美的 Plasma 桌面。</p><h4 id="如何获得-kde-plasma-5-24" tabindex="-1">如何获得 KDE Plasma 5.24 <a class="header-anchor" href="#如何获得-kde-plasma-5-24" aria-label="Permalink to “如何获得 KDE Plasma 5.24”">​</a></h4>',10)),l("p",null,[a[9]||(a[9]=t("KDE Plasma 5.24 现在可以在 KDE Neon 用户版，和通过 Backports PPA 在 Fedora 35 和 Kubuntu 21.10 上使用。如果你想重新安装，你可以从 ",-1)),p(s,{href:"https://neon.kde.org/download"},{default:e(()=>[...a[8]||(a[8]=[t("这里",-1)])]),_:1}),a[10]||(a[10]=t(" 下载它。",-1))]),a[31]||(a[31]=l("p",null,"如果你使用的是 Fedora 35 和 Kubuntu 21.10，请按照这些指南来获得这个版本。",-1)),l("ul",null,[l("li",null,[p(s,{href:"https://www.debugpoint.com/2022/02/upgrade-kde-plasma-5-24/"},{default:e(()=>[...a[11]||(a[11]=[t("在 Fedora 上升级 Plasma",-1)])]),_:1})]),l("li",null,[p(s,{href:"https://www.debugpoint.com/wp-admin/post.php?post=9018&action=edit"},{default:e(()=>[...a[12]||(a[12]=[t("如何在 Kubuntu 21.10 中安装 KDE Plasma 5.24",-1)])]),_:1})])]),a[32]||(a[32]=l("h3",{id:"结束语",tabindex:"-1"},[t("结束语 "),l("a",{class:"header-anchor",href:"#结束语","aria-label":"Permalink to “结束语”"},"​")],-1)),a[33]||(a[33]=l("p",null,"我为我们的网站点评测试过许多 Linux 发行版和桌面环境。没有哪个能在各个方面接近 KDE Plasma。我知道 GNOME 设计得很好，而且还有其他的小亮点，但是，当你需要一个省心的系统，而且几乎所有的自定义选项都开箱即用时，KDE Plasma 几十年来一直是赢家。",-1)),a[34]||(a[34]=l("p",null,"有的时候，为了让系统能在短时间内运行起来而无需太多折腾，我只有安装 KDE Plasma 才行。因为到最后，它肯定能工作，所有的选项都可以供你使用。",-1)),a[35]||(a[35]=l("p",null,"我认为运行 KDE Plasma 的 Kubuntu/Fedora 和 Linux Mint 是当今世界上最好的几个发行版，毫无疑问。",-1)),a[36]||(a[36]=l("p",null,"作为对本篇 KDE Plasma 5.24 点评的总结，我必须得承认，KDE Plasma 5.24 LTS 是该团队的一个本垒打。我们很高兴 KDE 的存在，并将在未来的日子里占据主导地位。",-1)),a[37]||(a[37]=l("p",null,"加油！",-1)),a[38]||(a[38]=l("hr",null,null,-1)),l("p",null,[a[14]||(a[14]=t("via: ",-1)),p(s,{href:"https://www.debugpoint.com/2022/03/kde-plasma-5-24-review/"},{default:e(()=>[...a[13]||(a[13]=[t("https://www.debugpoint.com/2022/03/kde-plasma-5-24-review/",-1)])]),_:1})]),l("p",null,[a[19]||(a[19]=t("作者：",-1)),p(s,{href:"https://www.debugpoint.com/author/admin1/"},{default:e(()=>[...a[15]||(a[15]=[t("Arindam",-1)])]),_:1}),a[20]||(a[20]=t(" 选题：",-1)),p(s,{href:"https://github.com/lujun9972"},{default:e(()=>[...a[16]||(a[16]=[t("lujun9972",-1)])]),_:1}),a[21]||(a[21]=t(" 译者：",-1)),p(s,{href:"https://github.com/wxy"},{default:e(()=>[...a[17]||(a[17]=[t("wxy",-1)])]),_:1}),a[22]||(a[22]=t(" 校对：",-1)),p(s,{href:"https://github.com/wxy"},{default:e(()=>[...a[18]||(a[18]=[t("wxy",-1)])]),_:1})]),l("p",null,[a[25]||(a[25]=t("本文由 ",-1)),p(s,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...a[23]||(a[23]=[t("LCTT",-1)])]),_:1}),a[26]||(a[26]=t(" 原创编译，",-1)),p(s,{href:"https://linux.cn/"},{default:e(()=>[...a[24]||(a[24]=[t("Linux中国",-1)])]),_:1}),a[27]||(a[27]=t(" 荣誉推出",-1))])])}const b=o(d,[["render",u]]);export{T as __pageData,b as default};
